/** Every label must belong to the org (other org: tenant error; unknown: not found). */
export async function assertLabelsInOrg(
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  const owners = await labelRepo.findLabelOrgs(labelIds);
  for (const id of labelIds) {
    const owner = owners.get(id);
    if (owner === undefined) throw new NotFoundError("Label", id);
    if (owner !== orgId) throw new TenantScopeError(orgId, owner);
  }
}

/** A parent must be a live issue of the same project. */
export async function assertValidParent(
  orgId: OrgId,
  projectId: string,
  parentId: IssueId,
): Promise<void> {
  const parent = await issueRepo.findIssueAnyOrg(parentId);
  if (!parent) throw new NotFoundError("Issue", parentId);
  if (parent.orgId !== orgId) throw new TenantScopeError(orgId, parent.orgId);
  if (isArchived(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** A reply target must be a live top-level comment on the same issue. */
export async function assertValidReplyTarget(
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId,
): Promise<void> {
  const parent = await commentRepo.findCommentAnyOrg(parentId);
