  if (parent.orgId !== orgId) throw new TenantScopeError(orgId, parent.orgId);
  if (
    isArchived(parent) ||
    parent.issueId !== issueId ||
    parent.parentId !== null
  ) {
    throw new NotFoundError("Comment", parentId);
  }
}
